    {(function(){/* Only members who can pick a day (an invitee cannot), and never once the day is agreed. */var _un=(ds.length&&!allAgreed)?inCrew.filter(function(m){return !m._me&&m._status==="confirmed"&&!ds.some(function(d){return (dayAcks[d]||[]).indexOf(m.id)>=0;});}):[];return _un.length?<button onClick={function(e){e.stopPropagation();_un.forEach(function(m){onNudge&&onNudge(crew.id,pubFirst(m),m.id);});}} style={{marginBottom:12,width:"100%",minHeight:44,padding:"9px",borderRadius:9,border:"1px solid "+C.blue,background:C.blueBg,color:C.onSolid,fontSize:12.5,fontWeight:700,cursor:"pointer"}}>{"Nudge "+_un.length+" to pick a day"}</button>:null;})()}
